	@field _cleanupShards (self: MemoryShard, maxEntriesPerShard: number?) -> Promise.TypedPromise<boolean>
	@field _removeKeyFromShard (self: MemoryShard, shardIndex: number, key: string) -> Promise.TypedPromise<boolean>
